              "3. ތަޝްރީޢީ ކަންތައްތައް: ދީނުގެ ޙުކުމްތައް ބަޔާންކޮށްދެއްވައި ޝަރުޢުކުރެއްވި ކަންކަން. މިއަށް ޢަމަލުކުރުން އުއްމަތުގެ މައްޗަށް ވާޖިބެވެ.",
              "4. ތަޝްރީޢީ ނޫން ދުނިޔަވީ ތަޖުރިބާގެ ކަންތައްތައް: ހަނގުރާމައިގެ އުކުޅުތަކާއި ދަނޑުވެރިކަން ފަދަ ދުނިޔަވީ ކަންކަން (މިސާލު: ބަދުރު ހަނގުރާމައިގައި الحُبَابُ بْنُ الْمُنْذِرُ ގެ މަޝްވަރާ ޤަބޫލުކުރެއްވުން، ކަދުރު ރުއްތައް ފޮޅިލުމުގެ ހާދިސާ)."
