              "2. ޣައިރު މުސްލިމުންގެ ދީނީ ޢީދުތަކާއި މުނާސަބާތްތައް (މިސާލު: ކްރިސްމަސް) ރޭވުމުގައި ބައިވެރިވުމާއި، އެފަދަ ޢީދުތަކުގެ ތަހުނިޔާ ކިޔުން.",
              "3. ކާފިރުންގެ ދީނީ ޝިޢާރުތަކަށް ރުހުމާއި އެތަކެތި މަތިވެރިކުރުން.",
              "4. ކާފިރުންގެ ޚާއްޞަ ދީނީ އާދަކާދަތަކާއި ސިފަތަކުގައި އެމީހުންނާ އެއްގޮތްވުން (تَشَبُّه).",
              "5. ޝަރުޢީ ޢުޛުރަކާ ނުލައި މުސްލިމުންނަށް ވުރެ ކާފިރުން އިސްކޮށް، އެމީހުން ޙިމާޔަތްކުރާ އެކުވެރީން ކަމުގައި ހެދުން.",
              "6. ކުފުރަށް ރުހުމާއި، މުސްލިމުންނާ ގުޅުން ކަނޑައިލުން."
