              "2. އަލްމަޙްދީ އަކީ 12 ވަނަ އިމާމުކަމާއި، އޭނާ ޣައިބަތުގައި (ދިރިހުރެ ފޮރުވިފައި) ވާކަމަށް ޤަބޫލުކުރުން.",
