              "4. ރަޖުޢަތަށް (ޤިޔާމަތްވުމުގެ ކުރިން ޢަލީގެފާނާއި އިމާމުންނާއި ޞަޙާބީން ދުނިޔެއަށް އެނބުރި އަންނާނެކަމަށް) ޤަބޫލުކުރުން.",
