          {
            heading: "3.5 – 3.6 ތާބިޢީންގެ ޒަމާނާއި ޙަދީޘް ޢިލްމުގެ ޚާއްޞަ ސިފަތައް",
            points: [
              "ތާބިޢީންގެ ޒަމާނުގައި (ހިޖުރީ 1 ވަނަ ޤަރުނުގެ ފަހުކޮޅު): ޚަލީފާ ޢުމަރު ބުން ޢަބްދުލްޢަޒީޒްގެ ރަސްމީ އަމުރުފުޅަށް އަބޫބަކުރު ބުން ޙަޒްމާއި އިމާމު މުޙައްމަދު ބުން މުސްލިމް ބުން ޝިހާބުއްޒުހުރީ ރަސްމީކޮށް ޙަދީޘް ޖަމާކުރެއްވިއެވެ.",
              "ތާބިޢީންގެ މަޝްހޫރު 6 ޞަޙީފާ: 1. ޞަޙީފަތު ސަޢީދު ބުން ޖުބައިރު، 2. ޞަޙީފަތު އަބިއްޒުބައިރު އަލްމައްކީ، 3. ޞަޙީފަތު ޒައިދު ބުން އަބީ އުނައިސާ، 4. ޞަޙީފަތު އަބީ ޤިލާބާ، 5. ޞަޙީފަތު އައްޔޫބުއްސަޚްތިޔާނީ، 6. ޞަޙީފަތު ހިޝާމް ބުން ޢުރުވާ.",
              "ޙަދީޘް ޢިލްމުގެ ޚާއްޞަ 3 ސިފަ: 1. ވަޙީގެ ދެވަނަ ބައިކަމުގައިވުން، 2. ކީރިތި ޤުރްއާނުގެ ޝަރަޙަކަމުގައިވުން، 3. ސަނަދާއި ރާވީން ދިރާސާކުރާ ތަފާތު ފަންނުތަކެއްގެ (مُصْطَلَحُ الْحَدِيث، عِلْمُ الْجَرْحِ وَالتَّعْدِيل، عِلْمُ تَرَاجِمِ الرِّجَال، عِلْمُ الطَّبَقَات) މައްޗަށް ބިނާވެފައިވުން.",
              "ޙަދީޘާ މެދު ޝައްކު އުފެއްދުމުގެ ޖާގަ ނެތްކަން (މުސްތަޝްރިޤުންނަށް ރައްދު): ކޮންމެ ޙަދީޘެއްގެ ސަނަދުގައި ހިމެނޭ ކޮންމެ ރާވީއެއްގެ ޢަދުލުވެރިކަމާއި ހަނދާނާއި ހިފެހެއްޓުންތެރިކަން (ޟަބްޠު) އަދި އުސްތާޛުންނާއި ދަރިވަރުންގެ ގުޅުން ތަޙުޤީޤުކުރެވިފައިވާތީ، ޙަދީޘާ މެދު ޝައްކުކުރުމުގެ ޖާގައެއް ނެތެވެ."
            ]
          }
