              "މުސްލިމު ޙާކިމުންނާއި ޤާބިލު މީހުންނަކީ ނިކަމެތިންނަށް އިޙްތިރާމްކޮށް، އެމީހުންގެ ޙައްޤުތައް ރައްކާތެރިކޮށް، ހުވަފަތް އަންހެނުންނާއި މިސްކީނުންނަށްޓަކައި މަސައްކަތްކުރާ ބަޔަކަށް ވާންޖެހެއެވެ (صحيح البخاري ومسلم)."
