        keyPoints: [
          {
            heading: "ޙަދީޘްގެ ޝަރަޙަ",
            points: [
              "އީމާންކަމާއި އަޚްލާޤުގެ ގުޅުން: ޞައްޙަ އީމާންކަމަކީ ރިވެތި އަޚްލާޤުން އޭގެ އަސަރު ފެންނަންޖެހޭ އެއްޗެކެވެ. ރަސޫލާ ﷺ ޙަދީޘްކުރެއްވިއެވެ: «إِنَّمَا بُعِثْتُ لِأُتَمِّمَ صَالِحَ الأَخْلَاقِ» (ތިމަންކަލޭގެފާނު ފޮނުއްވުނީ ރިވެތި އަޚްލާޤު ފުރިހަމަކޮށްދެއްވުމަށެވެ).",
              "މީޒާނުގައި އެންމެ ބަރުވާ ޢަމަލު: ޤިޔާމަތް ދުވަހު މުއުމިނާގެ މީޒާނުގައި އެންމެ ބަރުވެގެންވާނެ އެއްޗަކީ ރިވެތި އަޚްލާޤެވެ؛ އަދި ރިވެތި އަޚްލާޤުން ރޯދަވެރިޔާއާއި ރޭއަޅުކަންކުރާ މީހާގެ ދަރަޖަ ލިބެއެވެ.",
              "އަނބީންނަށް ހެޔޮކޮށް ހިތުން: މީހެއްގެ ޙަޤީޤީ އަޚްލާޤު ވަޒަންކުރެވޭ އެންމެ ބޮޑު މިންގަނޑަކީ ގޭތެރޭގައި އަނބިދަރީންނާ މުޢާމަލާތްކުރާ ގޮތެވެ. ބޭރު މީހުންނަށް ހިނިތުންވެފައި ގޭތެރޭގައި ހަރުކަށިވުމަކީ ފުރިހަމަ އީމާންކަމުގެ ސިފައެއް ނޫނެވެ."
            ]
          },
          {
            heading: "ޙަދީޘުން ލިބޭ 4 ފައިދާ",
            points: [
              "1. އަޚްލާޤު ރިވެތިވުމަކީ މުއުމިނާގެ އީމާންކަން ފުރިހަމަވެފައިވާކަމުގެ ދަލީލެއްކަން.",
              "2. އަނބީންނަށް ކަމޭހިތައި އޯގާތެރިވުމާއި ރިވެތިކޮށް މުޢާމަލާތްކުރުމަކީ އެންމެ ހެޔޮ މީހުންގެ ސިފައެއްކަން.",
              "3. އީމާންކަމުގައި މީސްތަކުން ތަފާތުވެ އުނިއިތުރުވާކަން (أَكْمَلُ الْمُؤْمِنِينَ).",
              "4. އިސްލާމްދީނުގައި ޢާއިލީ ގުޅުމަށާއި އަންހެނުންގެ ޙައްޤުތަކަށް ދެއްވާފައިވާ މަތިވެރި މަޤާމު."
            ]
          }
        ]
