              '3. ޣައިރު މުސްލިމު އަވައްޓެރިޔާ: 1 ޙައްޤު ލިބިގެންވެއެވެ (އަވަށްޓެރިކަމުގެ ޙައްޤު؛ ގާތްތިމާގެ މީހެއްނަމަ 2 ޙައްޤެވެ).'
