        keyPoints: [
          {
            heading: "ޢިއްފަތްތެރިކަމުގެ ޙުކުމާއި ދަލީލުތަކާއި އިސްލާމީ 5 ފިޔަވަޅު",
            points: [
              "ދަލީލު: ސޫރަތުއް ނޫރު 30-31 (މުއުމިނު ފިރިހެނުންނާއި މުއުމިނު އަންހެނުން ބެލުންތައް ތިރިކޮށް، ފަރުޖުތައް ރައްކާތެރިކޮށް، ޒީނަތްތެރިކަން ފާޅުނުކޮށް ޢައުރަ ނިވާކުރުމަށް އަމުރުކުރައްވާފައިވެއެވެ). އަދި ސޫރަތުއް ނޫރު 33 ގައި ކައިވެނި ނުކުރެވޭ މީހުން ޢިއްފަތްތެރިވެ ތިބުމަށް އަމުރުކުރެއްވިއެވެ.",
              "ޢިއްފަތްތެރި މުޖުތަމަޢެއް ބިނާކުރުމަށް އިސްލާމްދީން އަޅާފައިވާ 5 ފިޔަވަޅު: 1. ބެލުން ތިރިކުރުމަށް އަމުރުކުރުން، 2. ފުރިހަމަ ޝަރުޢީ ޙިޖާބުން ޢައުރަ ނިވާކުރުމަށް އަމުރުކުރުން، 3. ހިލޭ އަންހެނުންނާއި ފިރިހެނުން މަސްހުނިވުމާއި ޚަލްވަތުވުން މަނާކުރުން، 4. ކައިވެނިކުރުމަށް ބާރުއަޅައި ކައިވެނި ފަސޭހަކޮށްދިނުން، 5. ފާޙިޝް ކަންކަމަށް މަގުފަހިވާ ހުރިހާ ދޮރުތައް (ބަރަހަނާ މަންޒަރުތަކާއި، ގައިގޯޅިވުމާއި، ތަބައްރުޖުވުން) ޙަރާމްކުރުން."
            ]
          },
          {
            heading: "ޢިއްފަތްތެރިކަން ގެއްލުމުގެ ގެއްލުންތަކާއި ޢިއްފަތްތެރިކަމުގެ 7 ފައިދާ",
            points: [
              "ޢިއްފަތްތެރިކަން ގެއްލުމުގެ 5 ގެއްލުން: 1. ﷲ ގެ ކޯފާއާއި ޢަޛާބު ޙައްޤުވުން، 2. ނަސަބު އޮޅި ޢާއިލީ ނިޒާމު ހަލާކުވުން، 3. ނުރައްކާތެރި ޖިންސީ ބަލިތައް (އެއިޑްސް ފަދަ) ފެތުރުން، 4. މުޖުތަމަޢުގައި އިތުބާރާއި އަބުރު ގެއްލުން، 5. ނަފްސާނީ ބަލިކަށިކަމާއި ހިތްނުތަނަވަސްކަން ލިބުން.",
              "ޢިއްފަތްތެރިކަމުގެ 7 ފައިދާ: 1. ޢަރުޝީގެ ހިޔާވަހިކަން ލިބޭ 7 މީހުންގެ ތެރޭގައި ހިމެނުން، 2. ﷲ ގެ ލޯތްބާއި ސުވަރުގެ ލިބުން، 3. ހިތުގެ ސާފުކަމާއި އީމާންކަމުގެ ފޮނިކަން ލިބުން، 4. މީސްތަކުންގެ މެދުގައި ޤަދަރާއި އިޙްތިރާމް އުފުލުން، 5. ޞާލިޙު ޢާއިލާއަކާއި ޞާލިޙު ދަރިފަސްކޮޅެއް ބިނާވުން، 6. ބަލިތަކުން ރައްކާތެރިވުން، 7. ނުބައި ޝަހުވަތްތަކުގެ އަޅުވެތިކަމުން މިނިވަންވުން."
            ]
          }
        ]
